# Generated by build.py from recipe.yml for recipe http-time-out-an-idle-client. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--idle-timeout', '1', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --rate 1/3s -o NUL -o NUL -w "%{http_code} %{num_connects}\n" http://127.0.0.1:8080/hello.txt http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
